/// Polymorphic pointer to `ChatProviderSettingsBase`.
///
/// StrongPointer/WeakPointer fields declared with this base may
/// store any emitted subclass at runtime. Variants for types in
/// optional features are `#[cfg]`-gated; when their feature is
/// disabled at compile time, runtime dispatch falls through to
/// `Unknown { struct_index, instance_index }`.
#[derive(Debug, Clone)]
pub enum ChatProviderSettingsBasePtr {
    ChatProviderSettingsBase(Handle<ChatProviderSettingsBase>),
    #[cfg(feature = "dormant")]
    CodeDrivenChatProviderSettings(Handle<CodeDrivenChatProviderSettings>),
    #[cfg(any(
        feature = "entities-scitem-default_lensdisplay_pu",
        feature = "entities-ui"
    ))]
    AutoSubscribeChatProviderSettings(Handle<AutoSubscribeChatProviderSettings>),
    /// Runtime pointer to a subclass whose feature was disabled at
    /// compile time, or a type the generator doesn't know about.
    /// Use `Datacore::db()` + the two indices to walk the raw instance.
    Unknown {
        struct_index: u32,
        instance_index: u32,
    },
}

impl ChatProviderSettingsBasePtr {
    #[allow(dead_code)]
    pub(crate) fn from_ref<'a>(b: &mut Builder<'a>, r: svarog_datacore::InstanceRef) -> Self {
        let inst = b.db.instance(r.struct_index, r.instance_index);
        match inst.type_name() {
            Some("ChatProviderSettingsBase") => Self::ChatProviderSettingsBase(
                b.alloc_nested::<ChatProviderSettingsBase>(inst, true),
            ),
            #[cfg(feature = "dormant")]
            Some("CodeDrivenChatProviderSettings") => Self::CodeDrivenChatProviderSettings(
                b.alloc_nested::<CodeDrivenChatProviderSettings>(inst, true),
            ),
            #[cfg(any(
                feature = "entities-scitem-default_lensdisplay_pu",
                feature = "entities-ui"
            ))]
            Some("AutoSubscribeChatProviderSettings") => Self::AutoSubscribeChatProviderSettings(
                b.alloc_nested::<AutoSubscribeChatProviderSettings>(inst, true),
            ),
            _ => Self::Unknown {
                struct_index: r.struct_index,
                instance_index: r.instance_index,
            },
        }
    }
}

